<script>document.addEventListener('DOMContentLoaded',()=>{const body=document.getElementById('fis-satirlari'),total=document.getElementById('fis-toplam');let index=1;const money=n=>'₺'+Number(n||0).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2});function calc(){let sum=0;body.querySelectorAll('.fis-satir').forEach(r=>{const dahil=parseFloat(r.querySelector('.dahil').value)||0,oran=parseFloat(r.querySelector('.oran').value)||0,haric=dahil/(1+oran/100);r.querySelector('.haric').textContent=money(haric);r.querySelector('.kdv').textContent=money(dahil-haric);sum+=dahil});total.textContent=money(sum)}function bind(r){r.querySelectorAll('.dahil,.oran').forEach(e=>e.addEventListener('input',calc));r.querySelector('.sil').addEventListener('click',()=>{if(body.children.length>1){r.remove();calc()}})}bind(body.querySelector('.fis-satir'));document.getElementById('satir-ekle').addEventListener('click',()=>{const r=body.querySelector('.fis-satir').cloneNode(true);r.querySelectorAll('input').forEach(e=>{e.value='';e.name=e.name.replace(/\[\d+\]/,'['+index+']')});r.querySelector('select').name='satirlar['+index+'][kdv_orani]';r.querySelector('.haric').textContent='₺0,00';r.querySelector('.kdv').textContent='₺0,00';body.appendChild(r);bind(r);index++})})</script>
